from common import *

import numpy as np
from typing import *

# concepts:
# dominant_color, orientation_detection

# description:
# In the input grid, identify the dominant cyan (color 6) bands. 
# Determine if they are oriented as rows or columns.
# The output is a single value: 0 if the bands are rows, 1 if they are columns.

def main(input_grid: np.ndarray) -> int:
    # Initialize counters for cyan rows and columns
    cyan_row_count = 0
    cyan_col_count = 0

    # Check each row for dominant cyan
    for row in input_grid:
        if np.all(row == Color.TEAL):
            cyan_row_count += 1

    # Check each column for dominant cyan
    for col in input_grid.T:
        if np.all(col == Color.TEAL):
            cyan_col_count += 1

    # Determine orientation: 0 for rows, 1 for columns
    if cyan_row_count > cyan_col_count:
        return 0
    else:
        return 1

def generate_input() -> np.ndarray:
    # Define the grid dimensions
    width, height = 10, 10
    grid = np.random.choice(list(Color.NOT_BLACK), (width, height))

    # Randomly decide whether to create horizontal or vertical cyan bands
    if np.random.rand() > 0.5:
        # Create horizontal cyan bands
        for i in range(height):
            if np.random.rand() > 0.7:
                grid[i, :] = Color.TEAL
    else:
        # Create vertical cyan bands
        for j in range(width):
            if np.random.rand() > 0.7:
                grid[:, j] = Color.TEAL

    return grid
